1 void flee ()
2 {
3 // Desired velocity is the vector to the target .
4 desiredVelocity = ( rigidbody . position - target . position ) ;
5
6 // ... normalized and with the correct speed
7 desiredVelocity . Normalize () ;
8 desiredVelocity *= speed ;
9
