The route can be extracted easily by following the chain of parents from the
target to the start. We then reverse the route to return the path from start to
finish.
1 private static List <N > ExtractPath ( N target )
2 {
3 List <N > route = new List <N >() ;
4 N current = target ;
5 route . Add ( current ) ;
6
7 while ( current . parent != null )
8 {
9 route . Add ( current . parent ) ;
10 current = current . parent ;
11 }
12
13 route . Reverse () ;
14 return route ;
15 }
